// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/// @title SecureSessionVault - Encrypted storage with session management
/// @notice Manages user sessions and encrypted data storage
contract SecureSessionVault is Ownable {
    using ECDSA for bytes32;

    struct Session {
        bytes32 sessionId;
        uint256 createdAt;
        uint256 expiresAt;
        address boundAddress;
        bytes32 encryptionKeyHash;
        bool isActive;
    }

    struct EncryptedRecord {
        bytes encryptedData;
        bytes32 integrityHash;
        uint256 timestamp;
        bytes32 sessionRef;
    }

    mapping(bytes32 => Session) public sessions;
    mapping(address => bytes32) public activeSessionOf;
    mapping(bytes32 => EncryptedRecord[]) private vault;
    mapping(address => uint256) public nonces;

    uint256 public constant SESSION_DURATION = 1 hours;
    uint256 public constant MAX_RECORDS_PER_SESSION = 100;

    event SessionCreated(address indexed user, bytes32 indexed sessionId);
    event SessionInvalidated(address indexed user, bytes32 indexed sessionId);
    event DataStored(bytes32 indexed sessionId, uint256 recordIndex);

    error SessionExpired();
    error SessionNotActive();
    error InvalidSignature();
    error SessionAlreadyExists();
    error MaxRecordsReached();
    error Unauthorized();

    constructor() Ownable(msg.sender) {}

    /// @notice Initiates a new session with a pre-computed session ID
    /// @param proposedSessionId The session ID proposed by the client
    /// @param encKeyHash Hash of the client's encryption key
    /// @param signature EIP-712 signature authorizing session creation
    function initiateSession(
        bytes32 proposedSessionId,
        bytes32 encKeyHash,
        bytes memory signature
    ) external {
        bytes32 digest = keccak256(abi.encodePacked(
            "\x19Ethereum Signed Message:\n32",
            keccak256(abi.encode(
                "SessionInit",
                proposedSessionId,
                encKeyHash,
                nonces[msg.sender],
                block.chainid,
                address(this)
            ))
        ));

        address recovered = digest.recover(signature);
        if (recovered != msg.sender) revert InvalidSignature();

        // Invalidate any existing session for this user
        bytes32 existingSession = activeSessionOf[msg.sender];
        if (existingSession != bytes32(0)) {
            _invalidateSession(existingSession);
        }

        nonces[msg.sender]++;

        // Accept the client-proposed session ID directly
        // This binds the session to the user's address
        sessions[proposedSessionId] = Session({
            sessionId: proposedSessionId,
            createdAt: block.timestamp,
            expiresAt: block.timestamp + SESSION_DURATION,
            boundAddress: msg.sender,
            encryptionKeyHash: encKeyHash,
            isActive: true
        });

        activeSessionOf[msg.sender] = proposedSessionId;
        emit SessionCreated(msg.sender, proposedSessionId);
    }

    /// @notice Migrates a session to a new address (e.g., after key rotation)
    /// @param sessionId The session to migrate
    /// @param newOwner The new owner address
    /// @param ownerSig Signature from current session owner
    /// @param newOwnerSig Signature from new owner accepting the session
    function migrateSession(
        bytes32 sessionId,
        address newOwner,
        bytes memory ownerSig,
        bytes memory newOwnerSig
    ) external {
        Session storage session = sessions[sessionId];
        if (!session.isActive) revert SessionNotActive();
        if (block.timestamp > session.expiresAt) revert SessionExpired();

        bytes32 migrationDigest = keccak256(abi.encodePacked(
            "\x19Ethereum Signed Message:\n32",
            keccak256(abi.encode(
                "SessionMigrate",
                sessionId,
                newOwner,
                nonces[session.boundAddress],
                block.chainid
            ))
        ));

        address recoveredOwner = migrationDigest.recover(ownerSig);
        if (recoveredOwner != session.boundAddress) revert InvalidSignature();

        bytes32 acceptDigest = keccak256(abi.encodePacked(
            "\x19Ethereum Signed Message:\n32",
            keccak256(abi.encode(
                "AcceptMigration",
                sessionId,
                block.chainid
            ))
        ));

        address recoveredNew = acceptDigest.recover(newOwnerSig);
        if (recoveredNew != newOwner) revert InvalidSignature();

        // Migration: the session ID stays the same, only boundAddress changes
        // The new owner inherits the existing session with all its vault data
        address oldOwner = session.boundAddress;
        activeSessionOf[oldOwner] = bytes32(0);
        session.boundAddress = newOwner;
        activeSessionOf[newOwner] = sessionId;
        nonces[oldOwner]++;

        emit SessionInvalidated(oldOwner, sessionId);
        emit SessionCreated(newOwner, sessionId);
    }

    /// @notice Store encrypted data in the vault under the active session
    /// @param encryptedData The encrypted payload
    /// @param integrityHash Hash for integrity verification
    function storeEncrypted(
        bytes calldata encryptedData,
        bytes32 integrityHash
    ) external {
        bytes32 sessionId = activeSessionOf[msg.sender];
        Session storage session = sessions[sessionId];

        if (!session.isActive) revert SessionNotActive();
        if (block.timestamp > session.expiresAt) revert SessionExpired();
        if (session.boundAddress != msg.sender) revert Unauthorized();
        if (vault[sessionId].length >= MAX_RECORDS_PER_SESSION) revert MaxRecordsReached();

        vault[sessionId].push(EncryptedRecord({
            encryptedData: encryptedData,
            integrityHash: integrityHash,
            timestamp: block.timestamp,
            sessionRef: sessionId
        }));

        emit DataStored(sessionId, vault[sessionId].length - 1);
    }

    /// @notice Retrieve encrypted records for the caller's active session
    function getRecords() external view returns (EncryptedRecord[] memory) {
        bytes32 sessionId = activeSessionOf[msg.sender];
        Session storage session = sessions[sessionId];
        if (session.boundAddress != msg.sender) revert Unauthorized();
        return vault[sessionId];
    }

    /// @notice Invalidate the caller's current session
    function invalidateMySession() external {
        bytes32 sessionId = activeSessionOf[msg.sender];
        if (sessionId == bytes32(0)) revert SessionNotActive();
        _invalidateSession(sessionId);
        activeSessionOf[msg.sender] = bytes32(0);
        emit SessionInvalidated(msg.sender, sessionId);
    }

    function _invalidateSession(bytes32 sessionId) internal {
        sessions[sessionId].isActive = false;
    }

    /// @notice Check if a session is valid and not expired
    function isSessionValid(bytes32 sessionId) external view returns (bool) {
        Session storage session = sessions[sessionId];
        return session.isActive && block.timestamp <= session.expiresAt;
    }
}
